from sympy import isprime
import math

# Extended search: for each prime p, check all x,y with 1 <= x <= y <= p+3
# (since we proved y <= p and s = x+y <= p+3)
results = []
for p in range(2, 1000):
    if not isprime(p):
        continue
    for x in range(1, p+4):
        for y in range(x, p+4):
            if x**3 + y**3 == p * (x*y + p):
                results.append((p, x, y))

print("All solutions (p, x, y) with x <= y, p < 1000:")
for r in results:
    print(r)
print(f"\nTotal: {len(results)} solutions")
